import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type BookStatus = "reading" | "finished";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
};

export type NewBook = {
  title: string;
  author: string;
  notes: string;
};

export const LIMITS = { title: 200, author: 200, notes: 5000 } as const;

function dataFile(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function readAll(): Promise<Book[]> {
  let raw: string;
  try {
    raw = await readFile(dataFile(), "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
  // A file that exists but can't be parsed is an error, not an empty list:
  // treating it as empty would let the next write wipe out every book.
  const parsed: unknown = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error(`${dataFile()} does not contain a list of books`);
  }
  return parsed as Book[];
}

async function writeAll(books: Book[]): Promise<void> {
  const file = dataFile();
  await mkdir(path.dirname(file), { recursive: true });
  // Write to a temp file and rename so a crash mid-write can't leave a
  // half-written books.json behind.
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await rename(tmp, file);
}

// Serialise read-modify-write cycles so two requests arriving at once
// can't each read the old list and overwrite the other's change.
let queue: Promise<unknown> = Promise.resolve();

function update<T>(fn: (books: Book[]) => { books: Book[]; result: T }): Promise<T> {
  const run = queue.then(async () => {
    const { books, result } = fn(await readAll());
    await writeAll(books);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function listBooks(): Promise<Book[]> {
  await queue;
  return readAll();
}

export async function getBook(id: string): Promise<Book | undefined> {
  return (await listBooks()).find((b) => b.id === id);
}

export function validateNewBook(input: NewBook): string | null {
  if (!input.title) return "Title is required.";
  if (!input.author) return "Author is required.";
  if (input.title.length > LIMITS.title) return `Title must be at most ${LIMITS.title} characters.`;
  if (input.author.length > LIMITS.author) return `Author must be at most ${LIMITS.author} characters.`;
  if (input.notes.length > LIMITS.notes) return `Notes must be at most ${LIMITS.notes} characters.`;
  return null;
}

export function addBook(input: NewBook): Promise<Book> {
  const error = validateNewBook(input);
  if (error) return Promise.reject(new Error(error));

  const book: Book = {
    id: randomUUID(),
    title: input.title,
    author: input.author,
    notes: input.notes,
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  return update((books) => ({ books: [...books, book], result: book }));
}

/** Returns the updated book, or undefined if no book has that id. */
export function markFinished(id: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (!book || book.status === "finished") return { books, result: book };
    const updated: Book = { ...book, status: "finished", finishedAt: new Date().toISOString() };
    return { books: books.map((b) => (b.id === id ? updated : b)), result: updated };
  });
}

