import Link from "next/link";
import { connection } from "next/server";
import { listBooks, type Book } from "@/lib/books";
import { markFinishedAction } from "./actions";
import { AddBookForm } from "./add-book-form";

export default async function HomePage() {
  // Books live in a file that changes at runtime, so always read it per request.
  await connection();
  const books = await listBooks();

  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="muted">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
                <form action={markFinishedAction}>
                  <input type="hidden" name="id" value={book.id} />
                  <button type="submit" className="secondary">
                    Mark finished
                  </button>
                </form>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="muted">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Add a book</h2>
        <AddBookForm />
      </section>
    </>
  );
}

function BookLink({ book }: { book: Book }) {
  return (
    <Link href={`/books/${book.id}`} className="book-link">
      <span className="title">{book.title}</span>
      <span className="muted"> by {book.author}</span>
    </Link>
  );
}

