export function CopyLinkButton() {
  const [label, setLabel] = useState("Copy link to this book");

  async function copy() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setLabel("Link copied");
    } catch {
      // Clipboard access needs HTTPS or localhost; fall back to the address bar.
      setLabel("Couldn't copy — use the address bar");
    }
  }

  return (
    <button type="button" className="secondary" onClick={copy}>
      {label}
    </button>
  );
}

