export default async function BookPage(props: PageProps<"/books/[id]">) {
  await connection();
  const { id } = await props.params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <article>
      <p>
        <Link href="/">← All books</Link>
      </p>
      <h2 className="book-title">{book.title}</h2>
      <p className="muted">by {book.author}</p>
      <p>
        <span className={`badge ${book.status}`}>
          {book.status === "reading" ? "Currently reading" : "Finished"}
        </span>
        {book.finishedAt && (
          <span className="muted"> on {new Date(book.finishedAt).toLocaleDateString("en-GB", { dateStyle: "long" })}</span>
        )}
      </p>

      <h3>Notes</h3>
      {book.notes ? <p className="notes">{book.notes}</p> : <p className="muted">No notes.</p>}

      <CopyLinkButton />
    </article>
  );
}

