import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { addBook, getBook, listBooks, markFinished } from "./books";

let dir: string;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "nested", "books.json");
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await rm(dir, { recursive: true, force: true });
});

const sample = { title: "Middlemarch", author: "George Eliot", notes: "Slow start." };

describe("books store", () => {
  it("returns an empty list when the file doesn't exist yet", async () => {
    expect(await listBooks()).toEqual([]);
  });

  it("adds a book as currently reading and persists it to disk", async () => {
    const book = await addBook(sample);
    expect(book).toMatchObject({ ...sample, status: "reading", finishedAt: null });

    const onDisk = JSON.parse(await readFile(process.env.BOOKS_FILE!, "utf8"));
    expect(onDisk).toEqual([book]);
    expect(await getBook(book.id)).toEqual(book);
  });

  it("marks a book finished", async () => {
    const book = await addBook(sample);
    const updated = await markFinished(book.id);
    expect(updated?.status).toBe("finished");
    expect(updated?.finishedAt).toEqual(expect.any(String));
    expect((await getBook(book.id))?.status).toBe("finished");
  });

  it("returns undefined when marking an unknown book", async () => {
    expect(await markFinished("nope")).toBeUndefined();
  });

  it("doesn't lose books when several are added at once", async () => {
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => addBook({ ...sample, title: `Book ${i}` })),
    );
    expect(await listBooks()).toHaveLength(20);
  });

  it("rejects invalid books", async () => {
    await expect(addBook({ ...sample, title: "" })).rejects.toThrow("Title is required");
    await expect(addBook({ ...sample, author: "" })).rejects.toThrow("Author is required");
    expect(await listBooks()).toEqual([]);
  });

  it("refuses to overwrite a corrupt file", async () => {
    const file = path.join(dir, "books.json");
    process.env.BOOKS_FILE = file;
    await writeFile(file, "{ not json");
    await expect(addBook(sample)).rejects.toThrow();
    expect(await readFile(file, "utf8")).toBe("{ not json");
  });
});

