const base = "http://localhost:3123";
async function forms(path) {
  const html = await (await fetch(base + path)).text();
  return [...html.matchAll(/<form[^>]*>([\s\S]*?)<\/form>/g)].map(m => {
    const fd = new FormData();
    for (const h of m[1].matchAll(/<input type="hidden" name="([^"]+)"(?: value="([^"]*)")?/g)) fd.append(h[1], (h[2] ?? "").replace(/&quot;/g,'"').replace(/&amp;/g,'&'));
    return { fd, html: m[0] };
  });
}
async function submit(form, extra = {}) {
  for (const [k, v] of Object.entries(extra)) form.fd.append(k, v);
  const r = await fetch(base + "/", { method: "POST", body: form.fd, redirect: "manual" });
  return r.status;
}
